import java.nio.file.*;import java.util.*;import java.util.regex.*;
/** Build gate: JDBC acquisition must use try-with-resources or an explicit ownership-transfer boundary. */
public final class JdbcResourceSafetyCheck{
 private static final Set<String> MODULES=Set.of("GameCommon","ConfigCenter","Billing","AdminApi","Gateway","AooKernel");
 private static final Pattern ESCAPING=Pattern.compile("\\b(public|protected)\\s+(?:static\\s+)?(?:java\\.sql\\.)?(?:Connection|PreparedStatement|Statement|ResultSet|Stream\\s*<[^>]+>)\\s+\\w+\\s*\\(");
 public static void main(String[]args)throws Exception{Path root=Path.of(args[0]).toAbsolutePath();List<String>defects=new ArrayList<>();for(String module:MODULES){Path source=root.resolve("server").resolve(module).resolve("src/main");if(!Files.exists(source))continue;try(var paths=Files.walk(source)){for(Path file:paths.filter(value->value.toString().endsWith(".java")).toList())scan(file,defects);}}if(!defects.isEmpty()){System.err.println("JDBC resource ownership violations:");defects.forEach(value->System.err.println("  "+value));System.exit(1);}System.out.println("JDBC resource safety check passed.");}
 private static void scan(Path file,List<String>defects)throws Exception{String source=Files.readString(file);if(ESCAPING.matcher(source).find()&&!file.getFileName().toString().equals("DriverManagerDataSource.java"))defects.add(file+": JDBC resource type escapes public API");String[]lines=source.split("\\R",-1);for(int i=0;i<lines.length;i++){String line=lines[i];if(!(line.contains(".getConnection(")||line.contains("DriverManager.getConnection(")))continue;if(file.getFileName().toString().equals("DriverManagerDataSource.java"))continue;String context=(i>1?lines[i-2]:"")+(i>0?lines[i-1]:"")+line;if(!(line.contains("try (")||line.contains("try(")||context.contains("JDBC_OWNERSHIP_TRANSFER")))defects.add(file+":"+(i+1)+" acquisition lacks try-with-resources/ownership transfer");}}
}
